function renderSplit(){if(draft.created)return app(modal(success(),'split'));if(draft.step===0)return app(modal(`<p class="section-title">Choose an engagement</p>${modeChoices()}`,'split',footer()));return app(modal(`<div class="split-layout"><div>${modeChoices(true)}<div class="group"><p class="section-title">Client details</p>${details()}</div><div class="group"><p class="section-title">${draft.mode==='Monthly'?'Monthly service scope':'Custom plan & delivery work'}</p>${draft.mode==='Monthly'?monthly():custom()}</div></div>${summaryPanel()}</div>`,'split',footer('Create client & save scope →','create')));}
